        .summary-value {{ font-size: 2em; font-weight: bold; color: #667eea; }}
        .section {{ background: white; margin-bottom: 30px; padding: 20px; border-radius: 10px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }}
