WITH customer_sales AS (
  SELECT
    c.customer_id,
    COALESCE(SUM(p.amount), 0) AS total_amount,
    COUNT(r.rental_id) AS rental_count
  FROM customer c
  LEFT JOIN payment p ON c.customer_id = p.customer_id
  LEFT JOIN rental r ON c.customer_id = r.customer_id
  GROUP BY c.customer_id
),
cumulative_share AS (
  SELECT
    customer_id,
    total_amount,
    rental_count,
    SUM(total_amount) OVER (ORDER BY total_amount DESC) / SUM(total_amount) OVER () AS cumsum_ratio
  FROM customer_sales
),
top_10pct AS (
  SELECT customer_id
  FROM cumulative_share
  WHERE cumsum_ratio <= 0.10
  LIMIT 1 -- 确保至少取到边界客户（因浮点精度）
),
user_geo AS (
  SELECT
    c.customer_id,
    co.country
  FROM customer c
  JOIN address a ON c.address_id = a.address_id
  JOIN cityci ON a.city_id = ci.city_id
  JOIN country co ON ci.country_id = co.country_id
),
user_category_pref AS (
  SELECT
