INSERT INTO "col_etl_task" VALUES (2066899235819974657, 3, 'A03', '3', '水水顶顶顶', '1781622153607000', 1, 1, '174954643786848', '4', '19951942682', '[{"taskCode":"1781622153607000","x":0,"y":0}]', '', 0, NULL, NULL, 'PARALLEL', '0', 0, '1', '1', '超级管理员', 1, '2026-06-16 23:02:33.607000', '超级管理员', 1, '2026-06-22 20:16:56.643000', NULL, NULL, '{"id":"36","sqlData":{"id":"36","name":"create.table.dm8","type":"2","content":"-- 1. 建表\\\\nCREATE TABLE t_user\\\\n(\\\\n    id          INT IDENTITY(1,1) PRIMARY KEY,                      -- 自增主键\\\\n    username    VARCHAR(50) NOT NULL UNIQUE,                        -- 登录名，唯一\\\\n    password    VARCHAR(64) NOT NULL,                               -- 密码密文\\\\n    real_name   VARCHAR(50),                                        -- 真实姓名\\\\n    email       VARCHAR(100) UNIQUE,                                -- 邮箱，唯一\\\\n    phone       VARCHAR(20),                                        -- 手机号\\\\n    status      CHAR(1)   DEFAULT ''1'' CHECK (status IN (''0'', ''1'')), -- 状态 1=启用 0=禁用\\\\n    create_time TIMESTAMP DEFAULT SYSDATE,                          -- 创建时间\\\\n    update_time TIMESTAMP DEFAULT SYSDATE                           -- 更新时间\\\\n);\\\\n-- 2. 插入示例数据\\\\nINSERT INTO t_user (username, password, real_name, email, phone, status)\\\\nVALUES (''zhangsan'', ''e10adc3949ba59abbe56e057f20f883e'', ''张三'', ''zhangsan@demo.com'', ''13800000001'', ''1''),\\\\n       (''lisi'', ''25d55ad283aa400af464c76d713c...","description":"Dm8快速建表","validFlag":true,"delFlag":false,"createBy":null,"creatorId":null,"createTime":"2025-07-21 09:53:15","updateBy":null,"updaterId":null,"updateTime":"2025-07-21 09:53:15","remark":null},"queryParams":{"pageNum":1,"pageSize":6},"typaCode":"DM"}');
