INSERT INTO "tax_clean_rule" VALUES (8, '小数位统一', '1', '将数值字段统一保留指定的小数位数（如保留两位小数）', '1', '0', '千桐科技', 1, '2025-08-11 14:36:40', '千桐科技', 1, '2025-08-11 17:20:22', NULL, '“12.3” → “12.30”；“100” → “100.00”', '5', '将数值字段统一保留指定的小数位数（如保留两位小数）', 'FIX_TO_PRECISION', '008', 'A01A03', 1, '174954643786848');
INSERT INTO "tax_clean_rule" VALUES (9, '去除字段空格', '1', '去除字段中的前后空格或中间多余空格，提升匹配准确性', '1', '0', '千桐科技', 1, '2025-08-11 14:37:25', '千桐科技', 1, '2025-08-11 17:20:29', NULL, '“  山西 省  ” → “山西省”，收尾、中间等', '5', '去除字段中的前后空格或中间多余空格，提升匹配准确性', 'REMOVE_WHITESPACE', '009', 'A01A03', 1, '174954643786848');
INSERT INTO "tax_clean_rule" VALUES (10, '字段前缀/后缀统一', '1', '对字段值统一加前缀或后缀，或去除非业务所需的标记', '1', '0', '千桐科技', 1, '2025-08-11 14:37:45', '千桐科技', 1, '2025-08-11 17:20:36', NULL, '“编号123” → 去除“编号” → “123”', '5', '对字段值统一加前缀或后缀，或去除非业务所需的标记', 'ADD_PREFIX_SUFFIX', '010', 'A01A03', 1, '174954643786848');
INSERT INTO "tax_clean_rule" VALUES (11, '正则表达式替换', '1', NULL, '1', '0', '千桐科技', 1, '2025-08-11 14:37:55', '千桐科技', 1, '2025-08-11 17:20:43', NULL, NULL, '5', NULL, 'SIMPLE_REPLACE', '011', 'A01A03', 1, '174954643786848');
INSERT INTO "tax_clean_rule" VALUES (12, '超长字段截断', '1', '当字段长度超过指定长度时进行截断处理', '1', '0', '千桐科技', 1, '2025-08-11 14:38:37', '千桐科技', 1, '2025-08-11 17:14:21', NULL, '描述字段超100字符 → 截取前100字符', '6', '当字段长度超过指定长度时进行截断处理', 'STRING_SUBSTR', '012', 'A01A04', 1, '174954643786848');
INSERT INTO "tax_clean_rule" VALUES (13, '字段补零', '1', '在字段前/后补0，保持固定长度', '0', '0', '千桐科技', 1, '2025-08-11 14:38:52', '千桐科技', 1, '2025-08-11 17:14:17', NULL, '组织编码“1” → 补全为“00001”', '6', '在字段前/后补0，保持固定长度', NULL, '013', 'A01A04', 1, '174954643786848');
INSERT INTO "tax_clean_rule" VALUES (14, '数值空值填充', '1', '将空的数值字段填充为指定默认值（如 0、-1、平均数等）', '0', '0', '千桐科技', 1, '2025-08-11 14:45:35', '千桐科技', 1, '2025-08-11 17:14:11', NULL, '年龄字段为空 → 配置默认值为 0', '21', '将空的数值字段填充为指定默认值（如 0、-1、平均数等）', NULL, '014', 'A02A01', 1, '174954643786848');
