INSERT INTO "tax_clean_rule" VALUES (39, '清理过期记录', '1', '当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除', '1', '0', '千桐科技', 1, '2025-08-11 14:54:01', '千桐科技', 1, '2025-08-11 17:22:24', NULL, '最后登录时间早于30天前 → 该用户记录设为“过期”', '57', '当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除', 'CHECK_EXPIRATION', '039', 'A06A03', 1, '174954643786848');
INSERT INTO "tax_clean_rule" VALUES (40, '修正历史时间边界', '1', '当字段值早于系统可接受最早时间时，替换为指定边界值', '0', '0', '千桐科技', 1, '2025-08-11 14:54:16', '千桐科技', 1, '2025-08-11 17:10:19', NULL, '创建时间为“1900-01-01” → 替换为“2000-01-01”', '57', '当字段值早于系统可接受最早时间时，替换为指定边界值', NULL, '040', 'A06A03', 1, '174954643786848');
