INSERT INTO "tax_project" VALUES (2, '监测数据组', 2, '监测数据处理项目组，聚焦项目运行中的设备与系统监测数据（如传感器、日志、性能指标），负责本类数据的采集接入、清洗转换、模型构建与统一管理，支撑状态监控、异常预警及运维分析类数据服务。', '1', '0', '吴同', 2, '2025-09-18 14:53:29', '吴同', 2, '2025-09-22 19:21:26', NULL, '152317955043040', NULL, NULL);
INSERT INTO "tax_project" VALUES (3, '业务数据组', 2, '业务数据处理项目组，围绕水利项目核心业务流程，负责水量调度、工程巡检、防汛工单、水文记录等结构化数据的汇聚整合、标准治理与加工处理，支撑业务统计、过程追溯与管理决策类数据应用。', '1', '0', '吴同', 2, '2025-09-18 14:53:40', '吴同', 2, '2025-09-22 19:21:36', NULL, '152317966055136', NULL, NULL);
