INSERT INTO "tax_quality_cat" VALUES (12, '公共安全', 10, 0, 'A02A02', '防范和应对社会治安、安全生产、自然灾害等风险，保障人民生命财产安全和社会稳定。', '1', '0', '吴同', 2, '2025-09-18 16:12:10', '吴同', 2, '2025-09-18 16:12:10', NULL, 1, '174954643786848');
